package com.mo.economy_system.common.transfer;import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.check.*;import java.util.*;import org.junit.jupiter.api.Test;
class ClientFileCheckManifestAuthorizationStoreTest{@Test void successAndTruncatedAuthorizeActualEntriesAndReplace(){var s=new ClientFileCheckManifestAuthorizationStore(4);UUID t=UUID.randomUUID(),r=UUID.randomUUID();var ok=new ClientFileCheckResult(1,ClientFileCheckStatus.SUCCESS,ClientFileCheckType.MODS,List.of(new ClientFileCheckEntry("a.jar",1,"0".repeat(64))),List.of(),null);s.replace(t,r,ok,1);assertTrue(s.find(new ClientFileCheckManifestAuthorizationStore.Key(t,r,ClientFileCheckType.MODS,"a.jar"),1).isPresent());var truncated=new ClientFileCheckResult(1,ClientFileCheckStatus.TRUNCATED,ClientFileCheckType.MODS,List.of(new ClientFileCheckEntry("b.jar",2,"1".repeat(64))),List.of(),"FILE_LIMIT");s.replace(t,r,truncated,2);assertTrue(s.find(new ClientFileCheckManifestAuthorizationStore.Key(t,r,ClientFileCheckType.MODS,"a.jar"),2).isEmpty());assertTrue(s.find(new ClientFileCheckManifestAuthorizationStore.Key(t,r,ClientFileCheckType.MODS,"b.jar"),2).isPresent());s.replace(t,r,ClientFileCheckResult.failed(ClientFileCheckType.MODS,"X"),3);assertEquals(0,s.size(3));}@Test void expiryRollbackAndIsolation(){var s=new ClientFileCheckManifestAuthorizationStore();UUID t=UUID.randomUUID(),r=UUID.randomUUID();var result=new ClientFileCheckResult(1,ClientFileCheckStatus.SUCCESS,ClientFileCheckType.MODS,List.of(new ClientFileCheckEntry("a",0,"0".repeat(64))),List.of(),null);s.replace(t,r,result,100);assertEquals(1,s.size(100));assertEquals(0,s.size(0));}}
